        public static void BuildAndVerify()
        {
            PythonFacilityLayout.Build();PythonHousingSetup.VerifyAndCapture();var p=UnityEngine.Object.FindObjectOfType<ContentPreview>();p.Initialize();var client=p.GetComponent<PythonStateClient>();var f=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(client,p);var state=PythonServiceSetup.Sample();state.instance_id="facilities-ui";state.can_set_shifts=true;state.closed=false;state.required_action="";state.funds=3000;
            state.expansion=new PythonExpansion{seats=2,max_seats=8,next_seats=3,has_next=true,can_expand=true,cost=500,funds_after=500,operating_cost=60,next_operating_cost=70,details="現在の席数：2席 / 上限：8席\n次の増設：2 → 3席\n増設費用：500\n資金：1000 → 500\n日次運営費：60 → 70\n\n増設条件\n営業準備中・必要な確認への回答済み・増設後に資金が残ること。\n4～5席：人気目標の第1段階達成後\n6～8席：第2段階達成後\n\n新しい席は購入直後から使えます。飼育できる猫の上限は変わりません。\n増設当日から、休業日も日次運営費を精算します。\n\n増設履歴\n増設の記録はありません。"};
            state.rest_space=new PythonRestSpace{status="未購入",details="休養スペース：未購入 / 所持金：3000\n現在の追加回復：疲労＋0 / ストレス＋0\n\n在店して休養・療養する猫が対象です。疲労回復は特性の倍率を適用した後に加算します。\n購入・改修した日の閉店・休業から有効です。購入時には回復しません。\n出勤中・不在の猫には適用しません。療養日数は変えません。\n\n解放条件\n購入：出勤・病気ルールが有効な営業準備中\n強化：人気第1段階達成後\n防音改修：人気第2段階達成後・経営ルールが有効\n各操作は1回限り。支払い後に資金が残る必要があります。\n\n購入・設置：費用400 / 資金3000 → 2600 / 疲労＋10\n強化：費用800 / 疲労＋20\n防音改修：費用1000 / ストレス＋10\n\n購入・改修履歴\nまだ記録はありません。",notes="在店して休養・療養する猫が対象です。疲労回復は特性の倍率を適用した後に加算します。\n購入・改修した日の閉店・休業から有効です。購入時には回復しません。\n出勤中・不在の猫には適用しません。防音改修は休養ストレス回復のみ加算し、療養日数は変えません。",actions=new[]{new PythonRestSpaceAction{kind="purchase_rest_space",label="購入・設置",can_execute=true,cost=400,funds_after=2600,recovery_after=10},new PythonRestSpaceAction{kind="upgrade_rest_space",label="強化",reason="人気第1段階達成後",cost=800,funds_after=2200,recovery_after=20},new PythonRestSpaceAction{kind="soundproof_rest_space",label="防音改修",reason="人気第2段階達成後",cost=1000,funds_after=2000,stress_after=10}}};
            state.waiting_area=new PythonWaitingArea{status="未購入",capacity=4,max_wait_ticks=8,operating_cost=60,notes="購入・強化した日の営業から待機上限と待機猶予に適用します。\n当日から日次運営費が増え、休業日にも発生します。各操作は1回限りです。\n支払い後に資金が残る必要があります。席数や飼育枠は増えません。",details="待合スペース：未購入 / 所持金：3000\n現在：待機上限4人 / 待機猶予8刻\n待合の維持費0 / 日次運営費合計60\n\n購入・強化した日の営業から待機上限と待機猶予に適用します。\n当日から日次運営費が増え、休業日にも発生します。各操作は1回限りです。\n支払い後に資金が残る必要があります。席数や飼育枠は増えません。\n\n解放条件\n購入：人気第1段階達成後\n2段階目：購入済み・人気第2段階達成後\n営業準備中に操作できます。\n\n購入（1段階目）：費用800 / 資金3000 → 2200\n待機上限4 → 5人 / 待機猶予8 → 10刻\n維持費0 → 10 / 日次運営費60 → 70\n\n購入・強化履歴\nまだ記録はありません。",actions=new[]{new PythonWaitingAreaAction{kind="purchase_waiting_area",label="購入（1段階目）",can_execute=true,cost=800,funds_after=2200,capacity_before=4,capacity_after=5,wait_before=8,wait_after=10,daily_after=10,operating_before=60,operating_after=70},new PythonWaitingAreaAction{kind="upgrade_waiting_area",label="2段階目へ強化",reason="人気第2段階達成後",cost=1200,funds_after=1800,capacity_before=5,capacity_after=6,wait_before=10,wait_after=12,daily_before=10,daily_after=20,operating_before=70,operating_after=80}}};
            state.seat_equipment=new PythonSeatEquipment{can_manage=true,details="1席に設備1つ。移動・交換・取り外しは無料。取り外した設備は保管します。\n購入後に資金が残る必要があります。特別行動のテンション・体力消費は変更しません。",seats=new[]{new PythonEquipmentSeat{seat_id="seat-1",item_id="equipment-1",description="おもちゃセット（通常上昇：関心×1.2）"},new PythonEquipmentSeat{seat_id="seat-2",description="設備なし"}},catalog=new[]{new PythonEquipmentKind{kind_id="toys",name="おもちゃセット",effect="通常上昇：関心×1.2",cost=300,funds_after=700,can_purchase=true},new PythonEquipmentKind{kind_id="quiet_space",name="静かな交流スペース",effect="静かな交流の通常行動のみ：関心×1.35",cost=450,funds_after=550,can_purchase=true}},owned=new[]{new PythonOwnedEquipment{item_id="equipment-1",name="おもちゃセット",day=1,cost=300,effect="通常上昇：関心×1.2",seat_id="seat-1"},new PythonOwnedEquipment{item_id="equipment-2",name="くつろぎクッション",day=1,cost=300,effect="通常上昇：テンション×1.2"}}};
            state.expansion.funds_after=2500;state.expansion.details=state.expansion.details.Replace("資金：1000 → 500","資金：3000 → 2500");foreach(var kind in state.seat_equipment.catalog)kind.funds_after=state.funds-kind.cost;
            state.housing=new PythonHousingState{configured=true,count=6,capacity=6,free=0,stage=0,kind="purchase_housing",next_capacity=9,cost=500,funds_after=2500,daily_cost=0,next_daily_cost=20,operating_cost=60,next_operating_cost=80,can_expand=true};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});apply();p.GetComponent<PythonPreparationPanel>().Close();var menu=p.GetComponent<PythonMenuPanel>();var expansion=p.GetComponent<PythonExpansionPanel>();var equipment=p.GetComponent<PythonSeatEquipmentPanel>();var rest=p.GetComponent<PythonRestSpacePanel>();var waiting=p.GetComponent<PythonWaitingAreaPanel>();var housing=p.GetComponent<PythonHousingPanel>();
            var panels=new[]{expansion.panel,equipment.panel,rest.panel,waiting.panel,housing.panel};var closes=new[]{expansion.close,equipment.close,rest.close,waiting.close,housing.close};var summaries=new[]{expansion.summary,equipment.summary,rest.summary,waiting.summary,housing.summary};int[] routes={4,5,6,7};
            for(int i=0;i<5;i++){menu.Open();menu.SelectGroup(2);if(i<4)menu.Select(routes[i]);else menu.housingEntry.onClick.Invoke();Check(panels[i].activeSelf && closes[i].GetComponentInChildren<Text>().text=="メニューへ戻る","Facility menu navigation "+i);Check(!string.IsNullOrEmpty(summaries[i].text) && summaries[i].text.Contains("資金"),"Facility summary missing "+i);Canvas.ForceUpdateCanvases();Check(summaries[i].preferredHeight<=summaries[i].rectTransform.rect.height+1,"Summary clipped "+i);Capture(p,"Facility-"+i);closes[i].onClick.Invoke();Check(menu.panel.activeSelf && menu.SelectedGroup==2 && !panels[i].activeSelf,"Equipment group return lost "+i);}
            Check(menu.housingEntry.gameObject.activeSelf,"Housing equipment entry missing");menu.SelectGroup(0);Check(!menu.housingEntry.gameObject.activeSelf,"Housing shown in wrong group");menu.Close();housing.open.onClick.Invoke();Check(housing.close.GetComponentInChildren<Text>().text=="閉じる","Header housing retained menu context");housing.expand.onClick.Invoke();Check(housing.confirmation.activeSelf && housing.confirmationText.text.Contains("6 → 9") && housing.confirmationText.text.Contains("60 → 80"),"Housing consequences missing");Check(typeof(PythonStateClient).GetField("pending",f).GetValue(client)==null,"Housing expanded before confirm");Canvas.ForceUpdateCanvases();Check(housing.confirmationText.preferredHeight<=housing.confirmationText.rectTransform.rect.height+1,"Housing confirmation clipped");Capture(p,"FacilityHousingConfirm");housing.cancel.onClick.Invoke();Check(!housing.confirmation.activeSelf && state.housing.stage==0,"Housing cancel changed state");housing.Expand();state.revision++;apply();Check(!housing.confirmation.activeSelf,"Housing stale confirmation retained");housing.Disconnect();Check(!housing.expand.interactable && !housing.confirm.interactable,"Housing offline enabled");apply();housing.Close();
            Check(rest.details.text.Contains("費用") && rest.details.text.Contains("実行できない理由") && rest.details.text.Contains("回復"),"Rest cost/effect/reason missing");Check(waiting.details.text.Contains("購入後の資金") && waiting.details.text.Contains("実行できない理由") && waiting.details.text.Contains("待機猶予"),"Waiting cost/effect/reason missing");
            expansion.Open();expansion.Choose();CheckConfirmation(expansion.confirmationText);expansion.Cancel();equipment.Open();equipment.Purchase();CheckConfirmation(equipment.confirmationText);equipment.Cancel();rest.Open();rest.Purchase();CheckConfirmation(rest.confirmationText);rest.Cancel();waiting.Open();waiting.Purchase();CheckConfirmation(waiting.confirmationText);waiting.Cancel();Check(typeof(PythonStateClient).GetField("pending",f).GetValue(client)==null,"Cancelled facility action sent command");
            expansion.Choose();equipment.Purchase();rest.Purchase();waiting.Purchase();state.revision++;apply();Check(!expansion.confirmation.activeSelf && !equipment.confirmation.activeSelf && !rest.confirmation.activeSelf && !waiting.confirmation.activeSelf,"Revision retained facility confirmation");
            expansion.Disconnect();equipment.Disconnect();rest.Disconnect();waiting.Disconnect();Check(!expansion.proceed.interactable && !equipment.purchase.interactable && !rest.purchase.interactable && !waiting.purchase.interactable,"Offline facilities enabled");apply();
            state.expansion.can_expand=false;state.expansion.reason="6席への増設は第2段階達成後に解放されます。";state.housing.can_expand=false;state.housing.reason="購入後に資金が残る必要があります。";state.seat_equipment.can_manage=false;state.seat_equipment.reason="営業準備中に操作できます。";state.revision++;apply();Check(!expansion.proceed.interactable && expansion.notice.text.Contains("第2段階"),"Seat gate missing");Check(!housing.expand.interactable && housing.details.text.Contains("資金が残る"),"Housing gate missing");Check(!equipment.purchase.interactable && equipment.details.text.Contains("営業準備"),"Equipment gate missing");state.expansion.can_expand=true;state.expansion.reason="";state.housing.can_expand=true;state.housing.reason="";state.seat_equipment.can_manage=true;state.seat_equipment.reason="";state.revision++;apply();
            Action<string,Action,Action> queue=(kind,choose,confirm)=>{choose();Check(typeof(PythonStateClient).GetField("pending",f).GetValue(client)==null,"Choose sent command "+kind);confirm();var command=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);Check(command!=null && command.kind==kind,"Wrong command "+kind);typeof(PythonStateClient).GetField("pending",f).SetValue(client,null);state.revision++;apply();};
            queue("expand_seats",expansion.Choose,expansion.Confirm);queue("purchase_seat_equipment",equipment.Purchase,equipment.Confirm);queue("purchase_rest_space",rest.Purchase,rest.Confirm);queue("purchase_waiting_area",waiting.Purchase,waiting.Confirm);queue("purchase_housing",housing.Expand,housing.Confirm);state.housing.stage=1;state.housing.capacity=9;state.housing.free=3;state.housing.kind="upgrade_housing";state.housing.next_capacity=12;state.housing.cost=800;state.housing.funds_after=1700;state.funds=2500;state.revision++;apply();Check(housing.details.text.Contains("9 → 12") && housing.summary.text.Contains("上限：9"),"Housing updated state missing");queue("upgrade_housing",housing.Expand,housing.Confirm);
            menu.ResetFacilities();apply();foreach(var panel in panels)Check(!panel.activeSelf,"Same instance load retained facility");housing.Open();state.instance_id="loaded-game";apply();Check(!housing.panel.activeSelf && !housing.confirmation.activeSelf,"Load retained housing");state.housing=null;state.rest_space=null;state.waiting_area=null;state.seat_equipment=null;state.expansion=null;state.revision++;apply();menu.Open();menu.SelectGroup(2);Check(!menu.housingEntry.interactable && !menu.entries[4].interactable && !menu.entries[5].interactable && !menu.entries[6].interactable && !menu.entries[7].interactable,"Absent facilities enabled");Debug.Log("CAT_CAFE_FACILITY_UI_OK: five screens / menu and header / summaries / consequences / gates / cancellation / revision / offline / purchase commands / housing upgrade / reset");
        }
        static void CheckConfirmation(Text text){Canvas.ForceUpdateCanvases();Check(text.preferredHeight<=text.rectTransform.rect.height+1,"Facility confirmation clipped");}
        static void Capture(ContentPreview p,string name){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{p,"Logs/"+name+".png"});}
